window.kbParts["entries-dbbf82f26db90d2b"] = {"nodes":{"k-c04caeb6f9018c9b":{"review":{"definition":"具体问题具体分析要求找出特定事物或同一事物在特定阶段的矛盾特点，并据此选择处理方法。","explanation":"B项的“心病终须心药治”强调方法要对准问题性质，“解铃还须系铃人”强调从问题成因和相关当事人入手。两句都体现了根据问题的特殊性选择对策，因此B项对应成立。","references":[],"evidence":"心病终须心药治，解铃还须系铃人——具体问题具体分析","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4452ac06a25d9a53":{"review":{"definition":"六尺巷工作法是安徽省桐城市将六尺巷典故中的谦让、和合理念用于矛盾预防和纠纷化解的基层治理方法。它由党建引领，通过群众反映诉求、多方参与调解和网格治理等方式落实。","explanation":"在邻里纠纷中，群众可以先说清诉求，基层组织再协调多方参与，在依法明理的基础上引导当事人相互体谅、协商化解。③中的“谦和礼让、知进退、和为贵”对应这一工作法的文化内涵，因此③计入四个正确对应。","references":[{"source":"web-26c6f720eb96fdb4","location":"正文首段","quote":"谦和礼让、知进退、和为贵"}],"evidence":"谦和礼让、知进退、和为贵——“六尺巷工作法”","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-6c17be7420f2871c":{"review":{"definition":"在流域范围内统筹调查文化遗产和地方文化认知，比较各地材料，从中提炼最具代表性和辨识度的文化内容。","explanation":"凤凰河附近居民分别从文明起源、民族融合、拼搏奋斗精神等角度理解流域文化，既有考古调查又因遗产跨省市分布而无法整体推进。拟写建议时，应把调查范围与遗产分布范围对应起来，将整体推进调查作为提炼核心内容的前置措施。","references":[],"evidence":"整体推进调查研究，提炼文化核心内容","disposition":"练习技能","basis":"据原题和解析编释。"}},"k-d466b346c70affa7":{"review":{"definition":"组织招商服务时，可由工作组集中响应企业的具体需求，并通过领导小组和政企联合办公机制协调项目落地及后续发展中的事项。","explanation":"M市新区的招商服务工作组为腾夕材料公司快速准备项目书、协调配套企业，并按程序办理需要政府投资的事项。面对项目投资额大、涉及面广、手续繁琐的情况，新区还成立领导小组并建立政企联合办公机制。乐原市可据此在促成合作的部分提出对接新远眼镜公司的资金和配套需求，兼顾企业落地及后续经营。","references":[],"evidence":"我们创新了政企联","disposition":"练习技能","basis":"据原题和解析编释。"}},"k-108b14119f47b9b8":{"review":{"definition":"梳理已有产业基础及上下游配套，识别可以连接的技术、产品或服务环节，再选择能提高附加值的方向拓展产业链。","explanation":"N市从电脑代工起步，逐步实现零部件本地配套并形成向高端延伸的条件。M市利用煤化工基础，引入企业向功能性新材料延伸。乐原市可借鉴两地做法，以拟引进的眼镜制造为基础，布局视觉科技和智能制造，拓展VR、眼健康等关联领域，将这些内容写入合作后的产业发展部分。","references":[],"evidence":"扩展关联产业，构建高端视觉产业链","disposition":"练习技能","basis":"据原题和解析编释。"}},"k-3ca54ae4271964df":{"review":{"definition":"数量必须为整数时，先列不等式，再取满足条件的最小或最大整数。对严格下限，最小可行整数是下界向下取整后加1；对含等号的上限，最大可行整数是上界向下取整。","explanation":"只有乙设备消耗C零件，每台用9个，因此乙的台数必须大于100÷9，最少为12。每增加1台乙设备都会多用13个零件，取12台可为甲留下最多的零件。12台乙用掉156个，最多剩44个，而每台甲用16个，所以甲最多生产2台。生产12台乙和2台甲共用188个零件，其中C零件用108个，满足两项约束。","references":[],"evidence":"则乙设备数量最少为11+1=12个","disposition":"练习技能","basis":"据原题和解析编释。"}},"k-47d3f93ad044253d":{"review":{"definition":"先找出每个方案在各种可能状态下的最高收益，再选取最高收益最大的方案。","explanation":"副省级题表中，逐行比较可见三个方案的最高收益都出现在“销路好”一列，依次为180、240、100万元。240万元最高，所以第二问选方案二，与第一问的方案三组成D项。","references":[{"source":"web-393f68d469090f7e","location":"副省级第92题收益表，销路好列","quote":"更新生产线方案在不同情况下的收益"},{"source":"web-ad0ddadbf8e7759f","location":"第85题收益表，销路好列","quote":"更新生产线方案在不同情况下的收益"}],"evidence":"选择在最好自然状态下收益最大的方案作为最终方案","disposition":"练习技能","basis":"据原题与所列资料编释。","title":"大中取大法","related":[],"examFocus":{"国考 2023 副省级 行测#92":"用小中取大法和大中取大法时，先找出各方案的最低和最高收益，再分别在两组收益中比较。"}},"readings":[{"origin":"k-47d3f93ad044253d","title":"大中取大法","qs":["国考 2023 副省级 行测#92"],"definition":"先找出每个方案在各种可能状态下的最高收益，再选取最高收益最大的方案。","explanation":"副省级题表中，逐行比较可见三个方案的最高收益都出现在“销路好”一列，依次为180、240、100万元。240万元最高，所以第二问选方案二，与第一问的方案三组成D项。","evidence":"选择在最好自然状态下收益最大的方案作为最终方案","doubt":"","references":[{"source":"web-393f68d469090f7e","location":"副省级第92题收益表，销路好列","quote":"更新生产线方案在不同情况下的收益"}]},{"origin":"k-5fccd69feeab8b6b","title":"大中取大法","qs":["国考 2023 地市级 行测#85"],"definition":"先从各方案的收益中分别取最大值，再比较这些最大值，选择其中最大的方案。","explanation":"地市级题表中，“销路好”一列是各行的最高收益，方案一、二、三分别为180、240、100万元。新建生产线的240万元最高，所以答案组合的第二位是方案二，排除第二位为方案一的C项。","evidence":"选择在最好自然状态下收益最大的方案作为最终方案","doubt":"","references":[{"source":"web-ad0ddadbf8e7759f","location":"第85题收益表，销路好列","quote":"更新生产线方案在不同情况下的收益"}]}]},"k-799c394067efe0da":{"review":{"definition":"先从各方案的收益中分别取最小值，再比较这些最小值，选择其中最大的方案。","explanation":"地市级题表中，“销路差”一列是各行的最低收益，方案一、二、三分别为−40、−80、16万元。方案三在最差状态下仍有16万元收益，超过另两个方案的最低收益，所以排在答案组合的第一位。","references":[{"source":"web-ad0ddadbf8e7759f","location":"第85题收益表，销路差列","quote":"更新生产线方案在不同情况下的收益"},{"source":"web-393f68d469090f7e","location":"副省级第92题收益表，销路差列","quote":"更新生产线方案在不同情况下的收益"}],"evidence":"选择在最差自然状态下收益最大或损失最小的方案","disposition":"练习技能","basis":"据原题与所列资料编释。","title":"小中取大法","related":[],"examFocus":{"国考 2023 副省级 行测#92":"分别找出每个方案的最低收益和最高收益，再按两种决策方法比较各方案对应的收益。"}},"readings":[{"origin":"k-799c394067efe0da","title":"小中取大法","qs":["国考 2023 地市级 行测#85"],"definition":"先从各方案的收益中分别取最小值，再比较这些最小值，选择其中最大的方案。","explanation":"地市级题表中，“销路差”一列是各行的最低收益，方案一、二、三分别为−40、−80、16万元。方案三在最差状态下仍有16万元收益，超过另两个方案的最低收益，所以排在答案组合的第一位。","evidence":"选择在最差自然状态下收益最大或损失最小的方案","doubt":"","references":[{"source":"web-ad0ddadbf8e7759f","location":"第85题收益表，销路差列","quote":"更新生产线方案在不同情况下的收益"}]},{"origin":"k-fc73dc052c4260b8","title":"小中取大法","qs":["国考 2023 副省级 行测#92"],"definition":"先找出每个方案在各种可能状态下的最低收益，再选取最低收益最高的方案。","explanation":"副省级题表中，逐行比较可见三个方案的最低收益都出现在“销路差”一列，依次为−40、−80、16万元。16万元最高，所以第一问选方案三。","evidence":"选择在最差自然状态下收益最大或损失最小的方案","doubt":"","references":[{"source":"web-393f68d469090f7e","location":"副省级第92题收益表，销路差列","quote":"更新生产线方案在不同情况下的收益"}]}]},"k-1c7c3e831f555a3a":{"review":{"definition":"过洋牵星术是古代航海中利用牵星板观测星辰在地平线以上的高度，以判断船只所在纬度、辅助导航的方法。","explanation":"同一星辰在可比观测条件下的高度随观测地点的纬度而变。D项所说的“高度指数”对应星辰高度观测，“确定船只所处位置”在本题中指利用纬度信息辅助判断船位。","references":[],"evidence":"用牵星板测量所在地的星辰高度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-00f94bb51e3fd43c":{"review":{"definition":"1亿吨等于10000万吨。把以万吨表示的数值换算成以亿吨表示的数值时，用原数值除以10000。","explanation":"图1的柱形表示进口量，单位为万吨。2017—2021年五年的进口量合计为2389＋2367＋2351＋2107＋1892＝11106万吨，换算为1.1106亿吨，最接近D项的1.1亿吨。","references":[],"evidence":"约多少亿吨木材","disposition":"独立词条","basis":"据原题和解析编释。","title":"万吨与亿吨的换算","related":[],"examFocus":{"国考 2023 地市级 行测#121":"从图1读取2017—2021年各年的木材进口量，求和后将累计量由万吨换算为亿吨。","国考 2023 行政执法 行测#121":"读取图1中2017—2021年的木材进口量时，先确认柱形图的单位，再将五年累计量换算成题目要求的单位。"}},"readings":[{"origin":"k-00f94bb51e3fd43c","title":"万吨与亿吨的换算","qs":["国考 2023 行政执法 行测#121"],"definition":"1亿吨等于10000万吨。把以万吨表示的数值换算成以亿吨表示的数值时，用原数值除以10000。","explanation":"图1的柱形表示进口量，单位为万吨。2017—2021年五年的进口量合计为2389＋2367＋2351＋2107＋1892＝11106万吨，换算为1.1106亿吨，最接近D项的1.1亿吨。","evidence":"约多少亿吨木材","doubt":"","references":[]},{"origin":"k-468590eaf403df01","title":"万吨与亿吨的换算","qs":["国考 2023 地市级 行测#121"],"definition":"万吨和亿吨都是以吨为基础的质量单位。1亿吨等于10000万吨，将万吨数换算为亿吨数时除以10000。","explanation":"第121题问2017—2021年木材累计进口量。图1中这五年的进口量依次为2389、2367、2351、2107和1892万吨，合计11106万吨，换算为1.1106亿吨，最接近D项的1.1亿吨。","evidence":"我国总计进口了约多少亿吨木材？","doubt":"","references":[]}]},"k-1f3481a79834db19":{"review":{"title":"调查研究的务实要求","type":"方法与技能","definition":"2023年6月，习近平在内蒙古考察时要求在主题教育中抓好调查研究，在察实情、出实招、求实效上下功夫，即掌握真实情况、提出有针对性的措施并推动解决问题。","explanation":"开展调研时，可结合群众反映和现场情况核实问题，再根据查明的原因提出措施，跟踪问题解决情况。2023年7月，习近平在四川考察时提出，检验主题教育中的调查研究成效，要看是否摸清社情民意、是否解决实际问题。","basis":"据关联原题和解析编释。","references":[],"related":["k-57ce44cf155a5f30"],"examFocus":{"国考 2024 副省级 行测#3":"区分调查研究的过程要求和成效标准，核对各项表述分别说的是怎样调研还是如何检验结果。"}},"aspects":[{"title":"务实要求与调研成效检验","uses":[{"unit":"Q1","role":"直接考查","use":"②考查主题教育中开展调研的务实要求，③考查了解社情民意和解决实际问题这两项成效标准。两项均正确，全题共三项正确，选B。","evidence":"②要大兴务实之风，抓好调查研究，在察实情、出实招、求实效上下功夫③检验调查研究成效，要看是否摸清社情民意、是否解决实际问题","qids":["国考 2024 副省级 行测#3","国考 2024 地市级 行测#3"]}]}]},"k-d753024dbca81bbf":{"review":{"definition":"二手材料可以用来了解情况，亲身调研应摆在了解情况的首位，具有不可替代的作用。","explanation":"《习近平关于调查研究论述摘编》同时肯定了借助二手材料了解情况的必要性和亲身调研的优先地位。本题④把亲身调研的优先性推成了对二手材料的禁用，因此错误。","references":[],"evidence":"通过二手材料了解情况是必要的，但不能代替亲身调研。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-41613438ac29fc70":{"review":{"definition":"叶面施肥是将肥液喷施在叶面上的施肥方式。花卉叶面施肥通常宜选在较凉爽、湿度较高、风较小的早晨或傍晚。","explanation":"湿度较高、蒸发较慢时，肥液在叶面停留得更久，有利于吸收。早晨或傍晚往往具备这些条件，因此C项用“通常”概括适宜时段是正确的。","references":[],"evidence":"叶面施肥通常选择在早晨或傍晚进行","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a78ef40b11b53c12":{"review":{"definition":"水培花卉宜用洁净的水，酸碱度应适合所栽花卉。一般水培花卉可用偏酸性或中性的水。","explanation":"A项的“洁净”符合水质要求，问题在于把“偏碱性”也列为普遍要求。水的碱性过高会影响花卉生长，具体酸碱度应随品种调整，因此A项错误。","references":[],"evidence":"水培花卉应选用洁净的偏碱性的水","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f1683fc311e9cc73":{"review":{"definition":"压条是让仍与母株相连的枝条或茎蔓先在基质中生根，再将其分离成新植株的繁殖方法。月季、米兰等木本花卉常用此法。","explanation":"压条在生根前保留枝条与母株的连接，扦插通常先取下插穗，再促使其生根。许多多肉植物常用扦插或分株繁殖，B项把压条概括为多肉植物的常用繁殖方式，因此错误。","references":[],"evidence":"此法常用于木本花卉繁殖，如月季、米兰等","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d3dd3aebd531fc45":{"review":{"definition":"每一段内效率恒定时，工作量等于该段效率乘以时间。各人同期完成的工作量可以相加时，合作效率等于各人在合作状态下的实际效率之和。","explanation":"补全的题本显示，乙、丙15天完成第一段剩余量的2/3，占总量的1/2，末段乙独做11天完成总量的1/4。设总量为660，令甲、乙单独、丙的日效率分别为a、b、c，三段方程为6(a＋1.1b)＝165、15(1.1b＋c)＝330、11b＝165。解得b＝15、a＝11、c＝5.5，三人合作日效率为33，工期为20天，对应所给题本的B项。转载题本中20天排在D项。","references":[{"source":"web-80a121fd0142bc49","location":"数量关系，甲乙丙分段合作工程题","quote":"又完成剩余任务量的2/3"}],"evidence":"乙与他人合作时效率比其单独工作时高10%","disposition":"练习技能","basis":"据原题与所列资料编释。"}},"k-3da9cf45ef41c624":{"review":{"definition":"做类比推理题时，把每组词改写成“用甲制作乙”，检查两组词能否按相同的方向代入。","explanation":"C项可以依次读成“用牛皮纸制作纸袋”和“用柳条编制背筐”，两组都是材料在前、成品在后。A项也有对应关系，但左侧是物品到用途，右侧是用途到物品，方向相反。","references":[],"evidence":"牛皮纸是制作纸袋的原材料，柳条是制作背筐的原材料","disposition":"练习技能","basis":"据原题和解析编释。"}},"k-fe05d94adb7e19d7":{"review":{"definition":"部分量等于总体量乘以该部分占总体的比重。计算前应核对比重的分母与所用总体量在统计对象、范围和时期上是否一致。","explanation":"第135题③要用河北2013—2022年城镇累计新增就业人数748.4万人，乘以同一批新增就业人员中第三产业就业人员所占的比重。材料给出的46.6%是河北2021年第三产业就业人员占比，较2013年提高15.1个百分点，这两年的比重都无法确定整个区间内城镇新增就业人员的产业构成，因此③不能推出。①和②可以推出，共2项，选C。","references":[],"evidence":"天津和河北第三产业就业人员占比为60.5％和46.6%","disposition":"练习技能","basis":"据原题和解析编释。"}},"k-9dace9906e463a51":{"review":{"definition":"在清池村，冯教授团队顺应村民从生活中学习的习惯，通过共同动手改造村里的公共空间和自家庭院，带动村民参与乡村建设。","explanation":"最初的授课很少有村民愿意听。团队改从村民常聚的地方入手，用本地常见的毛竹和石头建了一把能坐能躺的“大椅子”。村民看到改造效果后，逐渐愿意开放自家庭院，邀请团队一起改造。老金用自家老物件办起家庭美术馆，并从参观者的欣赏中获得自豪感。这一过程对应本题“接近、启发村民”的做法。","references":[],"evidence":"尊重村民的学习习惯，和村民一起动手改造，逐步转变村民观念","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-2648d9806bee5091":{"review":{"definition":"隆金公司通过组建质量改进团队、收集质量问题信息并实施改进措施，持续保障汽车配件质量。","explanation":"材料以车门把手为例，说明配件瑕疵可能导致车门关不严或打不开。专门团队持续收集问题并落实改进，使影响使用和安全的质量问题有明确的处理途径。这对应本题“产品质量过硬”的原因。","references":[],"evidence":"组建质量改进团队、收集各种质量问题信息、实施质量改进措施","disposition":"题内说明","basis":"据原题和解析编释。","title":"汽车配件质量攻关","related":[],"examFocus":{"国考 2024 地市级 申论#2":"从给定资料2的车门把手案例中，提取隆金公司发现和处理配件质量问题的做法。","国考 2024 行政执法 申论#2":"从给定材料2的门把手案例和企业发展叙述中，提取质量管理、技术研发及市场表现方面的信息。"}},"readings":[{"origin":"k-2648d9806bee5091","title":"汽车配件质量攻关","qs":["国考 2024 地市级 申论#2"],"definition":"隆金公司通过组建质量改进团队、收集质量问题信息并实施改进措施，持续保障汽车配件质量。","explanation":"材料以车门把手为例，说明配件瑕疵可能导致车门关不严或打不开。专门团队持续收集问题并落实改进，使影响使用和安全的质量问题有明确的处理途径。这对应本题“产品质量过硬”的原因。","evidence":"组建质量改进团队、收集各种质量问题信息、实施质量改进措施","doubt":"","references":[]},{"origin":"k-35570b31203e03ac","title":"汽车配件质量攻关","qs":["国考 2024 行政执法 申论#2"],"definition":"隆金公司通过组建质量改进团队、收集质量问题信息和实施改进措施，持续解决汽车配件的质量问题。","explanation":"材料用车门关不严或打不开说明门把手瑕疵会危及驾乘安全，也说明开关次数和流畅度需要得到保障。持续质量攻关用于解释本题中的“产品质量过硬”。研发创新与技术迭代还推动产品扩展到十大系列，多项产品的市场占有率连续多年位居全国前三。","evidence":"组建质量改进团队、收集各种质量问题信息、实施质量改\n进措施","doubt":"","references":[]}]},"k-e95a77ceef8979c9":{"review":{"definition":"《习近平关于调查研究论述摘编》指出，通过二手材料了解情况是必要的，亲身调研具有不可替代的作用。","explanation":"二手材料可以补充对情况的了解，亲身调研能让调研者直接接触实际情况。第④项称“不能通过二手材料了解情况”，把二手材料不能替代亲身调研误解成了禁止使用二手材料。","references":[],"evidence":"通过二手材料了解情况是必要的，但不能代替亲身调研。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7a2dbbdd29c27954":{"review":{"definition":"回归预测用观测数据拟合因变量与自变量之间的关系，再用拟合模型估计新条件下的因变量取值或未来趋势。","explanation":"当历史数据中拟合出的关系在预测期间仍然适用时，可以用模型推测未来趋势。题中②说的是回归可以用历史数据做预测，这一用途成立。建立预测模型也无须先证明变量之间存在因果关系。","references":[],"evidence":"回归可以利用过去的数据预测未来的趋势","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-01d533c4acb86e9f":{"review":{"definition":"用总体量乘以比重求部分量时，先确认该比重以什么总体为分母，再核对所给总量的统计对象、范围和时期是否与之相同。","explanation":"第120题③中，748.4万人是河北2013—2022年城镇累计新增就业人数，46.6%是2021年河北第三产业就业人员占比。即使根据15.1个百分点的变化倒推2013年的占比，得到的也只是该年就业人员的产业占比。要用748.4万人推算③，还需要2013—2022年河北城镇累计新增就业人员中的第三产业占比。材料缺少这一口径的数据，因此③不能推出。","references":[],"evidence":"天津和河北第三产业就业人员占比为60.5％和46.6%","disposition":"练习技能","basis":"据原题和解析编释。"}},"k-c7eda7d36f597d42":{"review":{"definition":"储存易吸湿的化肥时，应保持环境干燥，并按肥料性质选择包装和容器。对金属有腐蚀性的化肥应避免直接接触易受腐蚀的金属器具。","explanation":"第20题中，防潮可减少化肥吸湿结块或养分损失。题解以过磷酸钙为例，指出选择容器还要考虑肥料对金属的腐蚀性。A项由防潮需求推出化肥普遍宜用金属器皿密封储藏，因此是本题要选出的错误说法。","references":[],"evidence":"化肥宜用金属器皿密封储藏，以防潮湿变质","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-54c7754c222bff05":{"review":{"definition":"常规经胸心脏超声从胸壁获取心脏图像，用于观察心脏结构和功能，通常无需空腹或憋尿。","explanation":"题中A项的“心脏超声”指常规经胸检查。它通过胸壁观察心脏，成像无需借助充盈的膀胱，也通常不受进食影响。A项在这个范围内成立，在选非题中应排除。","references":[],"evidence":"做心脏超声检查，无需患者做憋尿、空腹等特殊准备","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-56e71a6e3d70c581":{"review":{"definition":"血清抗体检测测量人体对幽门螺杆菌产生的抗体。尿素呼气试验利用幽门螺杆菌的尿素酶分解标记尿素，再根据呼出气体中的标记二氧化碳判断是否存在当前感染。","explanation":"感染清除后，血清抗体仍可能持续一段时间，因此抗体阳性难以区分既往感染与当前感染。在适用条件下，尿素呼气试验更适合判断当前感染。D项把血清检查称为判断感染的“最佳方法”，所以本题选D。","references":[],"evidence":"虽然血清检查可以检测幽门螺旋杆菌的抗体","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-99570a283a30f584":{"review":{"definition":"1亿等于10000万。以万为单位的数值换算成以亿为单位的数值时除以10000，反向换算时乘以10000。","explanation":"第121题表中的五年零售量均以万台计，相加得126528万台。选项以亿台划分区间，将合计数除以10000得12.6528亿台，约为12.7亿台，落在A项的12亿台至13亿台之间。","references":[],"evidence":"万台=12.7亿台，在A项范围内。","disposition":"练习技能","basis":"据原题和解析编释。"}},"k-ab9436ff69abc337":{"review":{"definition":"基期日均量等于基期总量除以基期内按统计口径计入的天数。已知现期总量和同比增速时，可用现期总量除以（1＋同比增速）求得上年同期总量。","explanation":"材料给出2023年三季度境内外币支付系统处理金额5707.35亿美元，同比下降14.63%。先用5707.35÷（1－14.63%）还原2022年三季度总金额，再除以该季度7至9月的日历天数（31＋31＋30＝92天），得到日均约72.67亿美元，落在B项的70亿至80亿美元之间。","references":[],"evidence":"金额5707.35亿美元，同比下降14.63%","disposition":"练习技能","basis":"据原题和解析编释。"}},"k-d3bcd8051f933120":{"review":{"definition":"两处产能都能在两类任务间切换时，可以比较同一处产能在两类任务上的机会成本，安排优先分工。求最短工期时，还可用统一折算后的最大日产能验证工期下界。","explanation":"40台机械需要120个A模块和80个B模块。甲少产1个B可多产2个A，乙少产1个B只能多产0.5个A，因此先让甲生产A、乙生产B。20天后A已齐，B还差40个，两车间合产8天可补齐。以1个A为1个产量单位、1个B为2个单位，甲每天最多产6个单位，乙最多产4个单位，总需求为280个单位，至少需要28天。该分工达到下界，选C。","references":[],"evidence":"甲车间每天可生产6个A模块或3个B模块，乙车间每天可生产1个A模块或2个B模块。","disposition":"练习技能","basis":"据原题和解析编释。"}},"k-cf376dc793750737":{"review":{"definition":"1亿元等于10000万元。金额由万元换算为亿元时除以10000，由亿元换算为万元时乘以10000。","explanation":"第121题先按图1的总放映场次选出上海、北京、成都，再将三城票房相加，得到49091万元。换算后为4.9091亿元，落在C项的4.75亿至5亿元之间。","references":[],"evidence":"18682+19324+11085=49091万元","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c76a2d6f2250fc77":{"review":{"definition":"大帆夜市在人流密集的街口利用警用无人机与地面警力联动开展路面巡控。巡查小组关注信息平台通知，发现拥堵后及时到场疏导。","explanation":"材料中，警用无人机用于人流量大的街道口巡控。20时15分夜市中段因车辆违规停留出现拥堵，巡查小组接到平台通知后赶赴现场疏导。指南应将街口巡控和接报后的现场疏导一并列入交通秩序维护。","references":[],"evidence":"巡查小组及时赶到现场进行交通疏导","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-e2e1a601abeb3d3b":{"review":{"definition":"“反诈体检”是大帆夜市“平安驿站”的互动式反诈宣讲活动。巡查小组了解参与者的投资理财习惯、金融知识水平和常用社交软件，识别高风险易受损群体并作重点提醒。","explanation":"材料中的俞女士对投资理财期望较高、金融知识有限，被列为高风险易受损群体。指南应把互动测试和重点提醒列入21点开始的安全知识宣讲。","references":[],"evidence":"常用社交软件等都纳入“反诈体检”项目","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-af2cde3ce9b40c79":{"review":{"definition":"三维反求工程是先对已有实物进行测量，再依据测量数据，通过三维几何建模重构实物数字化模型的方法。","explanation":"第89题按各步骤的输入和产出排序。③先获取零件表面各点的空间坐标，②再从测量数据中提取设计与加工特征，④用计算机辅助设计软件将数据和特征重构为三维模型，①最后制造样品，检验模型是否满足精度和其他性能指标。A、B把验证放在测量之前，C把验证放在建模之前，因此选D（③②④①）。","references":[],"evidence":"用一定的测量方法对实物进行测量，根据测量数据通过三维几何建模方法重构实物的数字化模型","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bb6c44731f7129ab":{"review":{"definition":"相对降幅是减少量占比较基准的百分比，等于（比较基准值－实际值）÷比较基准值×100%。","explanation":"本题以“十三五”时期（2016—2020年）的年均制作时长为比较基准。取表中制作综艺益智类广播节目时长一列，五年均值为（210.4＋210.6＋208.0＋199.5＋197.8）÷5＝205.26万小时。2021年制作时长为193.9万小时，相对降幅为（205.26－193.9）÷205.26×100%≈5.53%，保留一位小数为5.5%，选A。解析写作5.4%，按表中数据复算约为5.53%。","references":[],"evidence":"比“十三五”时期年均制作时长少","disposition":"练习技能","basis":"据原题和解析编释。"}},"k-0cb68a6ef8038007":{"review":{"definition":"求甲量是乙量的多少倍，用甲量除以乙量。乙量是比较基准，须非零，两量的单位须统一。","explanation":"第125题C项比较2021年两项节目制作时长。综艺益智类广播节目为193.9万小时，影视剧类电视节目为7.5万小时，193.9÷7.5≈25.9，因此C项可以直接从表中推出。标准解析对A项采用逐年同比口径，判断2016年是否增加还需要2015年数据。若只比较表内各年，2016年至2021年的影视剧类电视节目播出时长确实依次上升。","references":[],"evidence":"2021年我国制作综艺益智类广播节目时长是制作影视剧类电视节目时长的25.9倍","disposition":"练习技能","basis":"据原题和解析编释。"}},"k-814b56ec73f90e16":{"review":{"definition":"市场监管部门公开招募自愿报名的外卖配送员，经遴选和岗前培训后组建食品安全监管志愿队伍。","explanation":"材料5中，Y区平均每名执法人员要监管200多家餐饮单位，而配送员跑单时能直接接触商家。K区同样面临监管点多、线长、面广的难题，因此可借鉴Y区发布“召集令”的做法，把自愿报名、遴选和岗前培训写成组建队伍的具体步骤。","references":[],"evidence":"邀请外卖小哥自愿加入，并对应征者进行遴选、培训","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-43c6551ae6adf248":{"review":{"definition":"配送员志愿者发现食品安全隐患后，拍摄照片或视频并通过监管平台上报。市场监管部门接收线索、及时处置，并定期汇总分析监督情况。","explanation":"材料5中，小华发朋友圈后经转发引起监管部门注意。Y区随后用“食安宝”建立固定上报渠道，由志愿分队提供线索，处置分队处理并按月统计。给K区提建议时，可沿用这一分工，写清谁上报、通过什么渠道上报、谁负责处置。","references":[],"evidence":"根据食品安全隐患线索及时做出处理，并对每月监督情况进\n行统计分析。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-8262e928435d43df":{"review":{"definition":"针对紧急食品安全隐患，可利用报送人员的实时点位和现场信息，结合可用执法资源，就近调派执法人员。","explanation":"材料5中，N市应急管理部门收到“应急小哥”报送的信息后，可通过调度系统查看其点位、姓名和联系方式，匹配最近的可用应急力量。参考答案把这一做法用于K区的紧急食品安全隐患处置，作为在常规线索处理之外加快到场的建议。","references":[],"evidence":"针对紧急情况，就近匹配执法力量，快速协同处置。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-2816e2903b69f26b":{"review":{"definition":"依托配送行业党组织发挥党员配送员的示范作用，通过业务培训提升志愿者的食品安全宣传、沟通和监督能力。","explanation":"材料5中，N市成立外卖配送行业党委和小哥流动党员党支部，并开设“小哥先锋·食安卫士”培训班，讲授监管基础知识，指导配送员从消费者角度与商家沟通。给K区提建议时，这些做法针对队伍建成后的履职能力。材料另有应急部门为“应急小哥”开展情景模拟的做法，可为应急培训提供参考。","references":[],"evidence":"在志愿\n者队伍中发挥其模范带头作用。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-7fd993f4b786e0e7":{"review":{"definition":"通过与服务时长挂钩的积分福利、便于配送员使用的驿站服务和体现志愿贡献的活动，鼓励配送员持续参与志愿服务。","explanation":"材料5中，“食安宝”的“嘉许礼遇”向达到一定服务时长的志愿者提供折扣或兑换福利，爱心驿站提供休憩充电服务，“随手拍”作品展和“食安找茬”活动有助于增强归属感。K区可据此分别提出服务奖励、日常便利和活动激励三类措施。","references":[],"evidence":"制定积分奖励制度，按服务时长给予不同梯度的福利","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-5608d2dc6607c9c1":{"review":{"definition":"先确定包含全部合格结果且便于计数的范围，再用该范围的总数减去其中不合格的结果数。分情况统计不合格结果时，同一结果只扣一次。","explanation":"先暂时放宽五类文物都须展出的要求。首日从青铜器、瓷器、书法中选两类，有3种选法。此后三天每天从前一天未展出的三类里选两类，各有3种，共81种。任意相邻两天合计展出四个不同类别，所以最多漏掉一类。固定漏掉一类后，剩余四类的两组展品必须交替展出，首日选法就决定全程。漏玉器或国画各有3种，漏其余三类各有1种，故81－6－3＝72种，选A。","references":[],"evidence":"满足条件的情况数=总情况数-不满足条件的情况数","disposition":"练习技能","basis":"据原题和解析编释。"}},"k-e89bde83cca92477":{"review":{"definition":"原题引文：高分组（试卷总得分排在前27%的考生）该题的难度","explanation":"本题中，难度为1表示全员答对，两组答对率均为1，所以D为0，排除A。高分组答对率低于低分组时，D为负，排除B。100人中恰有27人答对时，这27人可以全部位于高分组，使D达到理论上限1，排除C。按答对得满分、答错得0分计，平均得分除以该题分值恰好等于全体考生的答对率，因此选D。公开转录对相减顺序的记载一致，原卷所用的变量符号仍待核对。","references":[{"source":"web-2b44235621cd2ef0","location":"第3.2.1节“计算公式”","quote":"D＝PH－PL"},{"source":"web-432c3fa7194dcbdf","location":"第102题题干","quote":"D=Ph−Pl"},{"source":"web-9ada55f8f57c3a15","location":"第19页，第102题题干","quote":"D=P1-P2"}],"evidence":"高分组（试卷总得分排在前27%的考生）该题的难度","disposition":"独立词条","basis":"据原题与所列资料编释。"}}}};
